/bin/bash -lc "python - <<'PY'
import os
req={os.path.splitext(f)[0] for f in os.listdir('/workspace/requirements') if f.endswith('.yaml')}
patch={os.path.splitext(f)[0] for f in os.listdir('/workspace/requirement_patches') if f.endswith('.diff')}
remaining=sorted(req-patch)
print(len(req), len(patch), len(remaining))
for r in remaining:
    print(r)
PY"

